/**
 * Generate Which Commands Stream, for `sdk.run()`
 *
 * `sdk.run()` takes raw CLI arguments and must decide between a `Promise`
 * and an `AsyncIterable` before it loads any command. This script reads the
 * `streams` marker of every command in the loaded route tree and writes them
 * out, so the runtime check comes from the command definitions instead of a
 * hand-kept list.
 *
 * The output is gitignored and regenerated by `generate:docs`, which runs as
 * part of `dev`, `build`, `bundle`, `typecheck`, and `test`.
 *
 * Usage:   pnpm ts script/generate.ts streaming-commands
 * Output:  src/generated/streaming-commands.json
 */

import { mkdirSync } from "node:fs";
import { writeFile } from "node:fs/promises";
import { routes } from "../src/app.js";
import type { RouteMap } from "../src/lib/introspect.js";
import { logger } from "../src/lib/logger.js";
import { collectStreamingCommands } from "../src/lib/streaming-commands.js";

const OUTPUT_PATH = "src/generated/streaming-commands.json";

/** Write the streaming mode of every streaming command. */
export async function emit(): Promise<void> {
  const commands = collectStreamingCommands(routes as unknown as RouteMap);

  mkdirSync("src/generated", { recursive: true });
  await writeFile(OUTPUT_PATH, `${JSON.stringify(commands, null, 2)}\n`);

  logger.success(
    `Generated ${OUTPUT_PATH} (${Object.keys(commands).length} commands)`,
  );
}
